// Writes public/build-info.json: which source commit a build was made from,
// so a deployed build can be identified (About shows it) and a rollback
// target can be picked with confidence. Git-ignored and regenerated by every
// build (scripts/build-verified.sh), same pattern as offline-manifest.json -
// never hand-edited or committed, so it always reflects the commit that was
// ACTUALLY checked out when the build ran, never a stale guess.
//
//   node scripts/generate-build-info.mjs

import { execFileSync } from "node:child_process";
import { writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const ROOT = fileURLToPath(new URL("../", import.meta.url));
const OUT = new URL("../public/build-info.json", import.meta.url);

function git(args) {
  try {
    return execFileSync("git", args, { cwd: ROOT, encoding: "utf8" }).trim();
  } catch {
    return "";
  }
}

export function buildInfo() {
  const commit = git(["rev-parse", "HEAD"]);
  // A build from a dirty working tree (uncommitted local changes) is said so
  // plainly - never presented as if it exactly matched a specific commit.
  const dirty = git(["status", "--porcelain"]) !== "" && commit !== "";
  return {
    commit: commit || null,
    commitShort: commit ? commit.slice(0, 7) : null,
    dirty,
    builtAt: new Date().toISOString(),
  };
}

function main() {
  const info = buildInfo();
  writeFileSync(fileURLToPath(OUT), `${JSON.stringify(info, null, 2)}\n`);
  console.log(
    `generate-build-info: commit ${info.commitShort ?? "(unknown - not a git checkout)"}` +
      `${info.dirty ? " (dirty working tree)" : ""} -> public/build-info.json`,
  );
}

const invokedDirectly = process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1];
if (invokedDirectly) main();
